class Solution {
public:
    int minGroupsForValidAssignment(vector<int>& nums) {
        unordered_map<int, int> cnt;
        for (int x : nums) cnt[x]++;
        vector<int> freqs;
        int m = 1e9;
        for (const auto& [_, f] : cnt) {
            freqs.push_back(f);
            m = min(m, f);
        }
        for (int k = m; k >= 1; k--) {
            int total_groups = 0;
            bool possible = true;
            for (int f : freqs) {
                int q = f / k, r = f % k;
                if (r > q) {
                    possible = false;
                    break;
                }
                total_groups += (f + k) / (k + 1);
            }
            if (possible) return total_groups;
        }
        return nums.size();
    }
};

class Solution {
    public int minGroupsForValidAssignment(int[] nums) {
        Map<Integer, Integer> cnt = new HashMap<>();
        for (int x : nums) cnt.put(x, cnt.getOrDefault(x, 0) + 1);
        List<Integer> freqs = new ArrayList<>(cnt.values());
        int m = Integer.MAX_VALUE;
        for (int f : freqs) m = Math.min(m, f);
        for (int k = m; k >= 1; k--) {
            int totalGroups = 0;
            boolean possible = true;
            for (int f : freqs) {
                int q = f / k, r = f % k;
                if (r > q) {
                    possible = false;
                    break;
                }
                totalGroups += (f + k) / (k + 1);
            }
            if (possible) return totalGroups;
        }
        return nums.length;
    }
}

/**
 * @param {number[]} nums
 * @return {number}
