var minGroupsForValidAssignment = function(nums) {
    const cnt = new Map();
    for (const x of nums) cnt.set(x, (cnt.get(x) || 0) + 1);
    const freqs = Array.from(cnt.values());
    let m = Math.min(...freqs);
    for (let k = m; k >= 1; k--) {
        let totalGroups = 0;
        let possible = true;
        for (const f of freqs) {
            const q = Math.floor(f / k), r = f % k;
            if (r > q) {
                possible = false;
                break;
            }
            totalGroups += Math.floor((f + k) / (k + 1));
        }
        if (possible) return totalGroups;
    }
    return nums.length;
};
